"""Generate the concise reviewer entry point from checked project outputs."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
m=json.loads((ROOT/'output/full/metrics.json').read_text())
r=json.loads((ROOT/'reporting/output/full/manifest.json').read_text())
p=json.loads((ROOT/'output/experiment-plan.json').read_text())
c=m['cart_trial_baseline']
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Commerce decision readout | Harshit Malik</title><meta name="description" content="A two-minute commerce decision readout: evidence, financial conditions, experiment constraints and reporting reliability."><link rel="canonical" href="https://portfolio-lac-five-10.vercel.app/projects/commerce-conversion/readout"><link rel="stylesheet" href="/projects/commerce-conversion/experiment/style.css"><style>.tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:30px 0}.tile{background:white;border:1px solid var(--line);padding:24px}.tile strong{display:block;font-size:36px;font-weight:500}.tile p{font-size:14px}.decision{background:#163e30;color:#fff;padding:28px;margin:24px 0}.decision h2{color:white;margin:0 0 14px}.decision p{max-width:880px}.decision a{color:#fff}.steps{display:grid;grid-template-columns:1fr 1fr;gap:22px}.steps article{border-top:1px solid var(--line);padding-top:18px}table{width:100%;border-collapse:collapse}th,td{padding:14px 10px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}th{background:#e6eee8}.scroll{overflow:auto}.small{font-size:14px;color:var(--muted)}.actions{display:flex;gap:20px;flex-wrap:wrap;margin:25px 0}.actions a{background:#163e30;color:white;padding:12px 18px;text-decoration:none;border-radius:4px}@media(max-width:760px){.tiles,.steps{grid-template-columns:1fr}table{min-width:650px}}@media print{header,.actions{display:none}body{background:white;font-size:11pt}main{max-width:none;padding:0}.tiles{grid-template-columns:repeat(3,1fr)}.decision{background:white;color:#163438;border:2px solid #163438}.decision h2{color:#163438}.tile{padding:12px}.tile strong{font-size:24px}a{color:#163438}.steps{display:block}.steps article{break-inside:avoid}h1{font-size:30pt}}</style></head><body><header><a href="/">HM / Portfolio</a><a href="/evidence">Evidence map</a><a href="https://github.com/harshit-malik-nyu/portfolio/tree/main/projects/commerce-conversion">Source &amp; methods</a></header><main><p class="eyebrow">HARSHIT MALIK / PRODUCT &amp; COMMERCIAL ANALYTICS</p><h1>Investigate the cart experience.<br>Make a rollout earn its funding.</h1><p class="intro">An independent decision study that connects customer behavior, investment conditions, experiment design and reporting controls. Start with the recommendation; inspect any number or rule below.</p><div class="decision"><h2>Decision: bounded investigation, followed by a measurable test.</h2><p>The historical data identifies a cart audience worth investigating. It does not show why customers leave or establish that a redesign will help. First verify tracking and diagnose a specific friction. Fund a rollout only after a valid experiment clears its economic and customer-harm thresholds.</p></div><div class="tiles"><article class="tile"><strong>@@ROWS@@</strong><p>Historical event rows processed. @@DUPES@@ exact duplicates collapsed before analysis.</p></article><article class="tile"><strong>@@RATE@@%</strong><p>@@BUYERS@@ of @@CART@@ first-cart visitors purchased within seven days, with complete observed follow-up.</p></article><article class="tile"><strong>@@TOTAL@@</strong><p>Illustrative required trial enrollment. This exceeds the @@CART@@ mature historical cart audience.</p></article></div><section><h2>What changes the business decision?</h2><div class="scroll"><table><thead><tr><th>Question</th><th>Evidence or condition</th><th>Action</th></tr></thead><tbody><tr><td>Is this a checkout failure?</td><td>The source has views, carts and transactions; no checkout-error or payment-attempt events.</td><td>Diagnose the friction and validate recording before selecting a remedy.</td></tr><tr><td>Would an improvement pay back?</td><td>Assumed $75 order value, 40% contribution margin and $8,000 fixed cost imply a @@MARGIN@@ percentage-point break-even lift.</td><td>Replace assumptions with approved economics before approving an experiment or rollout.</td></tr><tr><td>Can the trial answer the question?</td><td>Approximate primary-outcome planning needs @@ARM@@ independent visitors per arm, plus complete seven-day follow-up.</td><td>Confirm contemporary enrollment and guardrail power; hold if evidence is insufficient.</td></tr><tr><td>Can reporting be trusted?</td><td>Full-source daily reconciliation and a separate failure/recovery demonstration expose duplicate, late-data and invalid-refresh behavior.</td><td>Inspect the source hashes, metric definitions, audit records and failure handling.</td></tr></tbody></table></div><p class="small">Financial values are scenarios, not measured revenue or realized ROI. Sample planning is approximate and conditional; it is not an experiment result.</p></section><div class="actions"><a href="/projects/commerce-conversion/">Challenge the economics</a><a href="/projects/commerce-conversion/experiment/">Try a launch decision</a><a href="/projects/commerce-conversion/operations/">Inspect failure &amp; recovery</a></div><section><h2>From source file to a reviewable report</h2><p>A separate reporting implementation processed all @@ROWS@@ source rows in @@BATCHES@@ bounded input batches. Replaying the first batch inserted zero new rows. Twelve checks reconcile the source hash, daily totals, unique visitors, event types and order counts against the historical analysis.</p><p>@@DAYS@@ observed UTC dates reconcile to @@ORDERS@@ distinct visitor/transaction orders. Daily visitor counts are deliberately nonadditive. The first and last days may be partial; historical timestamps do not establish live completeness.</p><p><a href="/projects/commerce-conversion/reporting/output/full/daily.csv" download>Download the daily aggregate CSV</a> · <a href="/projects/commerce-conversion/reporting/output/full/manifest.json">Inspect the run manifest</a> · <a href="https://github.com/harshit-malik-nyu/portfolio/blob/main/projects/commerce-conversion/reporting/README.md">Reproduction &amp; BI handoff</a></p></section><section><h2>What each reviewer can inspect</h2><div class="steps"><article><h3>Data analysis</h3><p>Grain, distinct-order attribution, SQL reconciliation, nonadditive metrics and repeatable source checks.</p><a href="https://github.com/harshit-malik-nyu/portfolio/blob/main/projects/commerce-conversion/reporting/build.py">Inspect the reporting implementation</a></article><article><h3>Business analysis</h3><p>Alternatives, break-even conditions, requirements, proposed responsibilities and acceptance criteria.</p><a href="https://github.com/harshit-malik-nyu/portfolio/blob/main/projects/commerce-conversion/docs/decision-brief.md">Read the complete business decision</a></article><article><h3>Product analysis</h3><p>Visitor outcomes, observation windows, experimental validity, economics and customer-harm guardrails.</p><a href="/projects/commerce-conversion/experiment/">Challenge six experiment scenarios</a></article><article><h3>Personal ownership</h3><p>Ask for an explanation of the denominator, a failure prediction, or a live change. Published code is supporting evidence, not a pre-awarded interview score.</p><a href="https://github.com/harshit-malik-nyu/portfolio/blob/main/projects/commerce-conversion/operations/ownership-review.md">Open the ownership review guide</a></article></div></section><aside><strong>Scope:</strong> historical Retailrocket events from 2015, not a prospective employer's data. The reporting backfill uses that source; the operational and experiment labs use explicitly synthetic fixtures. No client commission, employer adoption, production deployment or realized financial impact is claimed.</aside><p class="small">Source and derived data attribution: Retailrocket, CC BY-NC-SA 4.0. Independent educational portfolio study. <a href="https://www.kaggle.com/datasets/retailrocket/ecommerce-dataset">Original dataset</a>.</p><p><a href="mailto:harshitmalik356@gmail.com">Discuss the business question and evidence</a> · <a href="/#experience">Relevant experience</a></p></main><footer>Harshit Malik · New York · SQL, Python, product and business decisions</footer></body></html>'''
values={'ROWS':f"{m['raw_rows']:,}",'DUPES':f"{r['duplicates_collapsed']:,}",'RATE':f"{c['rate']*100:.2f}",'BUYERS':f"{c['converted_visitors']:,}",'CART':f"{c['mature_visitors']:,}",'TOTAL':f"{p['total_n']:,}",'ARM':f"{p['approximate_n_per_arm']:,}",'MARGIN':f"{p['meaningful_margin']*100:.2f}",'BATCHES':str(r['input_batches']),'DAYS':str(r['reporting_days']),'ORDERS':f"{m['orders']:,}"}
for key,value in values.items():page=page.replace('@@'+key+'@@',value)
assert '@@' not in page
(ROOT/'readout.html').write_text(page+'\n')
print('Generated reviewer readout from checked outputs.')
